sys_script.script:
(function executeRule(current, previous) {
    var STEP = 'x_birl3_clm_key_approval_step';
    var reqId = current.getValue('request');
    var seq = current.getValue('sequence');

    // 1. Wait until every step in this stage is approved
    var open = new GlideAggregate(STEP);
    open.addQuery('request', reqId);
    open.addQuery('sequence', seq);
    open.addQuery('state', '!=', 'approved');
    open.addAggregate('COUNT');
    open.query();
    if (open.next() && parseInt(open.getAggregate('COUNT'), 10) > 0) return;

    // 2. This step completed the stage, so it is the last approver: its limit is final
    var finalLimit = parseFloat(current.getValue('approved_limit')) || 0;

    // 3. Fallback (e.g. approved without a limit): latest actioned step that has a limit
    if (!(finalLimit > 0)) {
        var last = new GlideRecord(STEP);
        last.addQuery('request', reqId);
        last.addQuery('sequence', seq);
        last.addQuery('approved_limit', '>', 0);
        last.orderByDesc('actioned_on');
        last.setLimit(1);
        last.query();
        if (last.next()) finalLimit = parseFloat(last.getValue('approved_limit')) || 0;
    }

    // 4. Stamp the stage's final limit on every step of the stage
    var up = new GlideRecord(STEP);
    up.addQuery('request', reqId);
    up.addQuery('sequence', seq);
    up.query();
    while (up.next()) {
        up.setValue('level_final_limit', finalLimit);
        up.setWorkflow(false);
        up.update();
    }
})(current, previous);
